// Clients chez qui on a pose une clim et sans entretien depuis (hors contrat de maintenance)
const now = DateTime.now().setZone('Europe/Paris');
// Horodatage commun a toutes les lignes de ce passage : l outil ne lit que le dernier passage
const maj = now.toUTC().toISO();
const test = s => {
  s = String(s || '').toLowerCase();
  if (/devis|visite technique|visite avant|metre|métré|chiffrage/.test(s)) return 'devis';
  if (/install|pose|mise en service/.test(s)) return 'installation';
  if (/d[ée]pannage|panne|fuite|erreur|ne fonctionne|ne fait plus|ne d[ée]marre/.test(s)) return 'depannage';
  if (/entretien|maintenance|nettoyage|r[ée]vision/.test(s)) return 'maintenance';
  return null;
};
const cat = ev => {
  const ti = String(ev.title || '').toLowerCase();
  // Une depose (travaux, stockage) sans repose n'est pas une installation
  if (/d[ée]pose/.test(ti) && !/repose/.test(ti)) return 'autre';
  return test(ev.type) || (ev.maintenance ? 'maintenance' : null) || test(ev.title) || 'autre';
};
const vus = new Set();
const C = {};
for (const it of $input.all()) {
  for (const ev of (it.json.items || [])) {
    if (vus.has(String(ev.id))) continue;
    vus.add(String(ev.id));
    if (ev.lifecycleState === 'cancelled' || !ev.client || !ev.client.id || ev.category === 'task') continue;
    const id = String(ev.client.id);
    const d = DateTime.fromISO(ev.start, { zone: 'utc' }).setZone('Europe/Paris');
    if (!d.isValid) continue;
    const c = C[id] || (C[id] = { nom: ev.client.name, install: null, maint: null, maintFuture: false, contrat: false });
    const k = cat(ev);
    // Contrat de maintenance actif : visite de contrat recente ou planifiee
    if (ev.maintenance && d > now.minus({ months: 18 })) c.contrat = true;
    if (k === 'installation' && ev.finished && d <= now && (!c.install || d > c.install.d)) c.install = { d, ev };
    if (k === 'maintenance') {
      if (d > now) c.maintFuture = true;
      else if (ev.finished && (!c.maint || d > c.maint)) c.maint = d;
    }
  }
}
const out = [];
for (const [id, c] of Object.entries(C)) {
  if (!c.install || c.contrat || c.maintFuture) continue;
  if (/^toshiba$/i.test(String(c.nom || '').trim())) continue;
  const ref = c.maint && c.maint > c.install.d ? c.maint : c.install.d;
  const mois = Math.floor(now.diff(ref, 'months').months);
  if (mois < 6) continue;
  const ev = c.install.ev;
  const m = String(ev.address || '').match(/(\d{5})[\s,]+(.+)$/);
  out.push({ json: {
    client_id: id, nom: String(c.nom || '').trim(), adresse: String(ev.address || ''), ville: m ? m[2].trim() : '',
    lat: ev.lat || null, lon: ev.lon || null,
    install_le: c.install.d.toISODate(), install_objet: [ev.type, ev.title].filter(Boolean).join(' : ').slice(0, 120),
    dernier_entretien: c.maint ? c.maint.toISODate() : '', mois, maj
  } });
}
return out;
